it('keeps oxygen and carbon-dioxide arrows opposite in both overview and barrier figures', () => {
  const s = session(file, { _regionalAtlasStep: 1 }), root = s.mount(), atlas = root.querySelector('[data-anatomy-atlas="alveoli"]');
  const oxygen = [...atlas.querySelectorAll('.anatomy-atlas-route[marker-end="url(#anatomy-arrow-oxygen)"]')];
  const carbon = [...atlas.querySelectorAll('.anatomy-atlas-route[marker-end="url(#anatomy-arrow-carbon)"]')];
  expect(oxygen).toHaveLength(2); expect(carbon).toHaveLength(2);
  expect(oxygen.map(route => route.closest('figure').getAttribute('data-anatomy-alveolus-scale'))).toEqual(['overview', 'barrier']);
  expect(carbon.map(route => route.closest('figure').getAttribute('data-anatomy-alveolus-scale'))).toEqual(['overview', 'barrier']);
  const oxygenInBarrier = oxygen[1].getAttribute('d'), carbonInBarrier = carbon[1].getAttribute('d');
  const verticalRoute = path => { const match = /^M\s*([\d.]+)\s+([\d.]+)\s*L\s*([\d.]+)\s+([\d.]+)$/.exec(path.trim()); expect(match).not.toBeNull(); return match.slice(1).map(Number); };
  const [ox1, oy1, ox2, oy2] = verticalRoute(oxygenInBarrier);
  const [cx1, cy1, cx2, cy2] = verticalRoute(carbonInBarrier);
  expect(ox1).toBe(ox2); expect(oy1).toBeLessThan(oy2);
  expect(cx1).toBe(cx2); expect(cy1).toBeGreaterThan(cy2);
  expect(ox1).not.toBe(cx1);
  expect(atlas.querySelector('marker#anatomy-arrow-oxygen path').getAttribute('fill')).toBe('#dc2626');
  expect(atlas.querySelector('marker#anatomy-arrow-carbon path').getAttribute('fill')).toBe('#2563eb');
  const key = atlas.querySelector('[data-anatomy-visual-key="alveoli"]'); expect(key).not.toBeNull();
  expect(key.textContent.toLowerCase()).toContain('oxygen'); expect(key.textContent.toLowerCase()).toContain('carbon dioxide');
  s.step(2)(); const next = s.mount().querySelector('[data-anatomy-atlas="alveoli"]');
  expect([...next.querySelectorAll('.anatomy-atlas-route.is-active')].every(route => route.getAttribute('marker-end') === 'url(#anatomy-arrow-carbon)')).toBe(true);
});

